use crate::hook_input::HookInput; use serde::{Serialize,Deserialize}; use std::{env,fs,io,path::PathBuf};
#[derive(Serialize,Deserialize,Default)] pub struct Session { pub session_id:String,pub turn_id:Option<String>,pub prompt:Option<String>,pub transcript_path:Option<String>,pub cwd:Option<String>,pub model:Option<String> }
pub fn dir()->PathBuf { env::var_os("XDG_STATE_HOME").map(PathBuf::from).or_else(||env::var_os("HOME").map(|p|PathBuf::from(p).join(".local/state"))).unwrap().join("compactveteran") }
pub fn save(i:&HookInput)->io::Result<()> { let id=i.session_id.clone().unwrap_or_else(||"unknown".into()); let s=Session{session_id:id.clone(),turn_id:i.turn_id.clone(),prompt:i.prompt.clone(),transcript_path:i.transcript_path.clone(),cwd:i.cwd.clone(),model:i.model.clone()}; let p=dir().join("sessions").join(format!("{id}.json")); fs::create_dir_all(p.parent().unwrap())?; let t=p.with_extension("tmp");fs::write(&t,serde_json::to_vec_pretty(&s).unwrap())?;fs::rename(t,p) }
